    code: `function dailyTemperatures(t: number[]): number[] {
  const ans = new Array(t.length).fill(0)
  const stack: number[] = []
  for (let i = 0; i < t.length; i++) {
    while (stack.length && t[i] > t[stack[stack.length - 1]]) {
      const j = stack.pop()!
      ans[j] = i - j
    }
    stack.push(i)
  }
  return ans
}`,
