    code: `function evalRPN(tokens: string[]): number {
  const st: number[] = []
  for (const t of tokens) {
    if (/^[+-]?\\d+$/.test(t)) st.push(parseInt(t))
    else {
      const b = st.pop()!, a = st.pop()!
      st.push(t === '+' ? a+b : t === '-' ? a-b : t === '*' ? a*b : Math.trunc(a/b))
    }
  }
  return st[0]
}`,
