    code: `function levelOrder(root: TreeNode | null): number[][] {
  if (!root) return []
  const q: TreeNode[] = [root], ans: number[][] = []
  while (q.length) {
    const sz = q.length, level: number[] = []
    for (let i = 0; i < sz; i++) {
      const n = q.shift()!
      level.push(n.val)
      if (n.left) q.push(n.left)
      if (n.right) q.push(n.right)
    }
    ans.push(level)
  }
  return ans
}`,
