    derivation: [],
    code: `function canPartition(nums: number[]): boolean {
  const sum = nums.reduce((a, b) => a + b, 0)
  if (sum % 2) return false
  const target = sum / 2
  const dp = new Array(target + 1).fill(false)
  dp[0] = true
  for (const x of nums)
    for (let s = target; s >= x; s--) dp[s] = dp[s] || dp[s - x]
  return dp[target]
}`,
