    code: `function flatten(root: TreeNode | null): void {
  let cur = root
  while (cur) {
    if (cur.left) {
      let p = cur.left
      while (p.right) p = p.right
      p.right = cur.right
      cur.right = cur.left
      cur.left = null
    }
    cur = cur.right
  }
}`,
