    code: `function partitionLabels(s: string): number[] {
  const last = new Map<string, number>()
  for (let i = 0; i < s.length; i++) last.set(s[i], i)
  const ans: number[] = []
  let start = 0, right = 0
  for (let i = 0; i < s.length; i++) {
    right = Math.max(right, last.get(s[i])!)
    if (i === right) {
      ans.push(right - start + 1)
      start = i + 1
    }
  }
  return ans
}`,
