    derivation: [
      "\u7B2C r \u884C\u957F\u5EA6\u4E3A r+1\u3002",
      "row[c] = \u4E0A\u4E00\u884C\u7684 [c-1] + [c]\u3002",
      "\u4E24\u7AEF c=0\u3001c=r \u76F4\u63A5\u4E3A 1\u3002"
    ],
    code: `function generate(numRows: number): number[][] {
  const ans: number[][] = []
  for (let r = 0; r < numRows; r++) {
    const row = new Array(r + 1).fill(1)
    for (let c = 1; c < r; c++)
      row[c] = ans[r - 1][c - 1] + ans[r - 1][c]
    ans.push(row)
  }
  return ans
}`,
