    code: `function twoSum(nums: number[], target: number): number[] {
  const map = new Map<number, number>() // \u503C -> \u4E0B\u6807
  for (let i = 0; i < nums.length; i++) {
    const need = target - nums[i]
    if (map.has(need)) return [map.get(need)!, i]
    map.set(nums[i], i)
  }
  return []
}`,
