    code: `function longestConsecutive(nums: number[]): number {
  const set = new Set(nums)
  let best = 0
  for (const x of set) {
    if (set.has(x - 1)) continue // \u4E0D\u662F\u8D77\u70B9
    let cur = x, len = 1
    while (set.has(cur + 1)) { cur++; len++ }
    best = Math.max(best, len)
  }
  return best
}`,
